{
  "core_question": "What analyses must the hospital board conduct across clinical, legal, and financial domains when converting a nonprofit community hospital to for‑profit ownership via private equity acquisition, sale‑leaseback of real estate, and spinning out a charitable foundation holding proceeds?",
  "rationale": "The transaction involves complex clinical service continuity concerns, intricate tax‑exempt status and regulatory compliance issues, and detailed financial structuring and valuation questions.",
  "routes": ["healthcare", "legal", "finance"],
  "sub_questions": {
    "healthcare": "What are the key clinical considerations—including patient care quality metrics, workforce retention strategies, Medicare/Medicaid eligibility, and potential impacts on community health outcomes—that the board should evaluate when a nonprofit rural hospital converts to for‑profit ownership under a private‑equity sponsor?",
    "legal": "From a legal standpoint, what due diligence steps, regulatory approvals, tax‑exempt status safeguards, sale‑leaseback compliance requirements, and fiduciary obligations must the board address to ensure the nonprofit conversion, charitable foundation spin‑out, and real estate transaction comply with federal (IRS 501(c)(3), CMS ownership rules) and state hospital licensing laws?",
    "finance": "What financial analyses—including valuation of the operating entity, leaseback structuring, debt financing terms, projected cash flows, tax implications for both the new for‑profit entity and the charitable foundation, and return expectations for the private‑equity sponsor—should the board review to assess the feasibility and desirability of this transaction?"
  },
  "requires_recency_disclosure": true,
  "recency_notes": "IRS 501(c)(3) sale‑leaseback guidance, CMS ownership restrictions, state hospital licensing updates, recent private equity deal structures."
}
